using System;using System.IO;using System.Reflection;using System.Text;
namespace PZ3D {static class ComponentEvidenceTests {static void Check(bool ok,string n){if(!ok)throw new Exception("FAIL "+n);}public static void Run(){Type t=typeof(Program).Assembly.GetType("PZ3D.ComponentEvidence");Check(t!=null,"component source/effective receipt evidence exists");var m=t.GetMethod("Compare");Func<string,string,string> compare=(local,remote)=>(string)m.Invoke(null,new object[]{local,remote});Check(compare("123","123")=="latest","equal official manifest latest");Check(compare("123","456")=="available","different official manifest update available");Check(compare("","456")=="missing","missing manifest not reported latest");Check(compare("123","")=="unknown","remote unknown never reported latest");string root=Path.Combine(LauncherTestPaths.Root,"evidence-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"steamapps/common/Game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);string code=Path.Combine(e.Workshop,"3814398576/mods/ViewpointSurface/42/mod.info");Directory.CreateDirectory(Path.GetDirectoryName(code));File.WriteAllText(code,"id=ViewpointSurface\nmodversion=1\n");string hash=ComponentEvidence.Fingerprint(e,"surface");ComponentEvidence.Record(e,"surface");File.SetLastWriteTimeUtc(code,DateTime.UtcNow.AddMinutes(1));Check(ComponentEvidence.Fingerprint(e,"surface")==hash,"unchanged bytes and manifest do not become update just from timestamp");File.WriteAllText(code,"id=ViewpointSurface\nmodversion=2\n");var state=ComponentEvidence.Decorate(e,"surface",new{configured=true});Check((string)state["sourceState"]=="changed"&&(bool)state["needsReapply"],"changed author bytes require reapply without rewriting config");Directory.CreateDirectory(e.BuddyLib);File.WriteAllText(Path.Combine(e.BuddyLib,"ZombieBuddy.jar"),"source");File.WriteAllText(Path.Combine(e.BuddyLib,"zbNative.dll"),"source");Directory.CreateDirectory(Path.Combine(e.Workshop,"3809306528","mods","Viewpoint"));var disabled=ComponentEvidence.Decorate(e,"base",new{configured=false});Check(!(bool)disabled["needsReapply"],"normal disabled base not falsely classified as deployed loader drift");Console.WriteLine("PASS component update evidence fixtures");}public static int Main(){try{Run();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}}
